// Мигание светодиодом на D2 (обычно GPIO2)
#define LED_PIN 2

void setup() {
  pinMode(LED_PIN, OUTPUT);
  }

  void loop() {
    digitalWrite(LED_PIN, HIGH);  // включить
      delay(1000);                  // 1 секунда
        digitalWrite(LED_PIN, LOW);   // выключить
          delay(1000);                  // 1 секунда
          }
